+function valueIsSuperset(left: unknown, right: unknown): boolean {
+	// strings must only be contained in the new string
+	if (typeof left === 'string' && typeof right === 'string') {
+		return stringContainsParts(right, left);
+	}
+	if (Array.isArray(left) || Array.isArray(right)) {
+		if (!Array.isArray(left) || !Array.isArray(right) || left.length !== right.length) return false;
+		return left.every((x, i) => valueIsSuperset(x, right[i]));
+	}
+	if (left && right && typeof left === 'object' && typeof right === 'object') {
+		const l = left as Record<string, unknown>;
+		const r = right as Record<string, unknown>;
+		const leftKeys = Object.keys(l);
+		if (leftKeys.length !== Object.keys(r).length) return false;
+		return leftKeys.every(
+			(k) => Object.prototype.hasOwnProperty.call(r, k) && valueIsSuperset(l[k], r[k]),
+		);
+	}
+	// everything else must be exactly equal to not be lost data
+	return left === right;
+}
